            try { evalString(code); }
            catch (FeatureNotBuilt& e) { featThrow = true; fe = e; }
            catch (RakuError& e) { if (!regexBlockErrorStaysQuiet(e)) rakuErr = std::current_exception(); } // a `die` in a block LEAVES the parse (Rakudo) — re-raised after the restores
            catch (...) {}
